pub fn validate_partitions(
    files: &[ListingFileSample<'_>],
    table_partition_fields: &[FieldRef],
) -> Result<()> {
    if table_partition_fields.is_empty() {
        return Ok(());
    }
    let inferred = infer_partitions(files)?;
    if inferred.is_empty() {
        return Ok(());
    }

    for group in files {
        if !group.url.is_collection() {
            return plan_err!(
                "Can't create a partitioned table backed by a single file, \
            perhaps the URL is missing a trailing slash?"
            );
        }

        let table_partition_names = table_partition_fields
            .iter()
            .map(|f| f.name().clone())
            .collect::<Vec<_>>();

        if inferred.len() < table_partition_names.len() {
            return plan_err!(
                "Inferred partitions to be {:?}, but got {:?}",
                inferred,
                table_partition_names
            );
        }

        // Match prefix to allow creating tables with partial partitions.
        for (idx, col) in table_partition_names.iter().enumerate() {
            if inferred.get(idx) != Some(col) {
                return plan_err!(
                    "Inferred partitions to be {:?}, but got {:?}",
                    inferred,
                    table_partition_names
                );
            }
        }
    }
    Ok(())
}

pub fn infer_partitions(files: &[ListingFileSample<'_>]) -> Result<Vec<String>> {
    let mut inferred: Option<Vec<String>> = None;
    for group in files {
        for file in &group.objects {
            let path_parts = group
                .url
                .strip_prefix(&file.location)
                .ok_or_else(|| {
                    internal_datafusion_err!(
                        "failed to strip listing prefix from object location: {}",
                        file.location
                    )
                })?
                .collect::<Vec<_>>();

            let keys = path_parts
                .into_iter()
                .rev()
                .skip(1) // get parents only and skip the file itself
                .rev()
                .filter(|s| s.contains('='))
                .map(|s| s.split('=').next().unwrap_or("").to_string())
                .filter(|s| !s.is_empty())
                .collect::<Vec<_>>();

            match &mut inferred {
                None => inferred = Some(keys),
                Some(x) if x == &keys => {}
                Some(x) => {
                    return plan_err!("found mixed partition values {x:?} and {keys:?}");
                }

pub fn can_be_evaluated_for_partition_pruning(
    partition_column_names: &[&str],
    expr: &Expr,
) -> bool {
    if partition_column_names.is_empty() {
        return false;
    }
    // Stable functions can prune partitions because their values do not change
    // within a query. DataFusion's listing helper only accepts immutable UDFs.
    let unsupported = expr.exists(|expr| {
        Ok(match expr {
            Expr::Column(column) => !partition_column_names.contains(&column.name.as_str()),
            Expr::ScalarFunction(function) => {
                function.func.signature().volatility == Volatility::Volatile
            }
            Expr::HigherOrderFunction(function) => {
                function.func.signature().volatility == Volatility::Volatile
            }
            Expr::Literal(_, _)
            | Expr::Alias(_)
            | Expr::Not(_)
            | Expr::IsNotNull(_)
            | Expr::IsNull(_)
            | Expr::IsTrue(_)
            | Expr::IsFalse(_)
            | Expr::IsUnknown(_)
            | Expr::IsNotTrue(_)
            | Expr::IsNotFalse(_)
            | Expr::IsNotUnknown(_)
            | Expr::Negative(_)
            | Expr::Cast(_)
            | Expr::TryCast(_)
            | Expr::BinaryExpr(_)
            | Expr::Between(_)
            | Expr::Like(_)
            | Expr::SimilarTo(_)
            | Expr::InList(_)
            | Expr::Case(_)
            | Expr::Lambda(_)
            | Expr::LambdaVariable(_) => false,
            _ => true,
        })
    });
    matches!(unsupported, Ok(false))
}

/// Given a schema and a list of partition column names, returns the partition fields
/// and a schema with the partition columns removed.
/// Exact names take precedence over the unique case-insensitive fallback.
pub fn get_partition_columns_and_file_schema(
    schema: &Schema,
    partition_by: Vec<String>,
) -> Result<(Vec<FieldRef>, Schema)> {
    let partition_fields = partition_by
        .into_iter()
        .map(|col| {
            let has_exact = schema.fields().iter().any(|field| field.name() == &col);
            let mut candidates = schema.fields().iter().filter(|field| {
                field.name() == &col || (!has_exact && field.name().eq_ignore_ascii_case(&col))
            });
            match (candidates.next(), candidates.next()) {
                (Some(field), None) => Ok(field.clone()),
                _ => {
                    plan_err!("missing or ambiguous partition column: {col}")
                }
            }
        })
        .collect::<Result<Vec<_>>>()?;
    let file_schema_fields = schema
        .fields()
        .iter()
        .filter(|f| !partition_fields.iter().any(|p| f.name() == p.name()))
        .cloned()
        .collect::<Vec<_>>();
    let file_schema = Schema::new(file_schema_fields);
    Ok((partition_fields, file_schema))
}

